import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null) return;

        int n = Integer.parseInt(line.trim());

        HashSet<String> exact = new HashSet<>();

        @SuppressWarnings("unchecked")
        HashSet<String>[] pref = new HashSet[11];
        @SuppressWarnings("unchecked")
        HashSet<String>[] suff = new HashSet[11];

        for (int i = 1; i <= 9; i++) {
            pref[i] = new HashSet<>();
            suff[i] = new HashSet<>();
        }

        for (int k = 0; k < n; k++) {
            String s = br.readLine().trim();

            boolean invalid = exact.contains(s);

            if (!invalid) {
                for (int p = 1; p <= 9; p++) {
                    String prefix = s.substring(0, p);
                    String suffix = s.substring(p);

                    if (suff[p].contains(prefix) && pref[10 - p].contains(suffix)) {
                        invalid = true;
                        break;
                    }
                }
            }

            if (invalid) {
                System.out.println(s);
                return;
            }

            exact.add(s);

            for (int p = 1; p <= 9; p++) {
                pref[p].add(s.substring(0, p));
                suff[p].add(s.substring(10 - p));
            }
        }

        System.out.println("ok");
    }
}
